import sys
import argparse
import json
import re
import subprocess

def parse_scalar(v):
    v = v.strip()
    if v == 'true': return True
    if v == 'false': return False
    if v == 'null': return None
    try:
        if '.' in v: return float(v)
        return int(v)
    except ValueError:
        if (v.startswith('"') and v.endswith('"')) or (v.startswith("'") and v.endswith("'")):
            return v[1:-1]
        return v

def parse_yaml_doc(lines, indent=0):
    res = None
    while lines:
        line = lines[0]
        if not line.strip() or line.strip().startswith('#'):
            lines.pop(0)
            continue

        cur_indent = len(line) - len(line.lstrip())
        if cur_indent < indent:
            break

        line = line.strip()
        if line.startswith('- '):
            if res is None: res = []
            val = line[2:].strip()
            lines.pop(0)
            if not val:
                res.append(parse_yaml_doc(lines, cur_indent + 1))
            else:
                res.append(parse_scalar(val))
        elif ':' in line:
            if res is None: res = {}
            key, val = line.split(':', 1)
            key = key.strip()
            val = val.strip()
            lines.pop(0)
            if not val:
                res[key] = parse_yaml_doc(lines, cur_indent + 1)
            else:
                res[key] = parse_scalar(val)
        else:
            val = line
            lines.pop(0)
            return parse_scalar(val)
    return res

def to_yaml(obj, indent=0, list_item=False):
    prefix = " " * indent
    if list_item:
        prefix = prefix[:-2] + "- "

    if isinstance(obj, dict):
        if not obj: return "{}"
        res = []
        for i, (k, v) in enumerate(obj.items()):
            p = prefix if i > 0 or not list_item else " " * (indent - 2) + "- "
            if isinstance(v, (dict, list)) and v:
                res.append(f"{p}{k}:")
                res.append(to_yaml(v, indent + 2))
            else:
                res.append(f"{p}{k}: {to_yaml(v, 0)}")
        return "\n".join(res)
    elif isinstance(obj, list):
        if not obj: return "[]"
        res = []
        for v in obj:
            res.append(to_yaml(v, indent + 2, list_item=True))
        return "\n".join(res)
    elif isinstance(obj, str):
        if "\n" in obj:
            lines = obj.splitlines()
            res = ["|"]
            for l in lines: res.append(" " * indent + l)
            return "\n".join(res)
        if any(c in obj for c in ":[]{},"): return f'"{obj}"'
        return obj
    elif obj is True: return "true"
    elif obj is False: return "false"
    elif obj is None: return "null"
    else: return str(obj)

def run_jq(data, exp):
    # Simple strenv replacement
    exp = re.sub(r'strenv\((.*?)\)', r'env.\1', exp)
    process = subprocess.Popen(['jq', '-c', exp], stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
    stdout, stderr = process.communicate(input=json.dumps(data))
    if process.returncode != 0:
        return [None] # Or handle error
    results = []
    for line in stdout.splitlines():
        if line.strip():
            results.append(json.loads(line))
    return results

def main():
    if '--version' in sys.argv or '-V' in sys.argv:
        print("yq (https://github.com/mikefarah/yq/) version v4.52.5")
        return

    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument('-o', '--output-format', default='yaml')
    parser.add_argument('-p', '--input-format', default='auto')
    parser.add_argument('-r', '--unwrapScalar', action='store_true', default=True)
    parser.add_argument('-i', '--inplace', action='store_true')
    parser.add_argument('expression', nargs='?', default='.')
    parser.add_argument('files', nargs='*')

    args_list = sys.argv[1:]
    if args_list and args_list[0] in ['eval', 'eval-all']:
        args_list = args_list[1:]

    args, unknown = parser.parse_known_args(args_list)

    # Handle files or stdin
    if not args.files:
        files = [sys.stdin]
    else:
        files = args.files

    for file_path in files:
        if file_path == sys.stdin:
            content = sys.stdin.read()
        else:
            with open(file_path, 'r') as f:
                content = f.read()

        # Determine format
        fmt = args.input_format
        if fmt == 'auto' and isinstance(file_path, str):
            if file_path.endswith('.json'): fmt = 'json'
            elif file_path.endswith(('.yaml', '.yml')): fmt = 'yaml'
            else: fmt = 'yaml' # default
        elif fmt == 'auto':
            fmt = 'yaml'

        if fmt == 'json':
            data_docs = [json.loads(content)]
        else:
            # Multi-doc YAML
            docs = re.split(r'^---$', content, flags=re.MULTILINE)
            data_docs = []
            for doc in docs:
                if doc.strip():
                    lines = doc.splitlines()
                    data_docs.append(parse_yaml_doc(lines))

        output_docs = []
        for data in data_docs:
            results = run_jq(data, args.expression)
            for res in results:
                output_docs.append(res)

        # Output
        out_fmt = args.output_format
        if out_fmt == 'auto':
            if isinstance(file_path, str) and file_path.endswith('.json'): out_fmt = 'json'
            else: out_fmt = 'yaml'

        output_str = ""
        for i, doc in enumerate(output_docs):
            if out_fmt == 'json':
                output_str += json.dumps(doc, indent=2) + "\n"
            else:
                if i > 0: output_str += "---\n"
                if isinstance(doc, (dict, list)):
                    output_str += to_yaml(doc) + "\n"
                else:
                    output_str += str(doc) + "\n"

        if args.inplace and isinstance(file_path, str):
            with open(file_path, 'w') as f:
                f.write(output_str)
        else:
            sys.stdout.write(output_str)

if __name__ == "__main__":
    main()
