        return int(v)
    except ValueError:
        if (v.startswith('"') and v.endswith('"')) or (v.startswith("'") and v.endswith("'")):
            return v[1:-1]
        return v

def parse_yaml_doc(lines, indent=0):
    res = None
    while lines:
        line = lines[0]
        trimmed = line.lstrip()
        if not trimmed or trimmed.startswith('#'):
            lines.pop(0)
            continue
        cur_indent = len(line) - len(trimmed)
        if cur_indent < indent:
            break

        if trimmed.startswith('- '):
            if res is None: res = []
            val = trimmed[2:].strip()
            if not val:
                lines.pop(0)
                res.append(parse_yaml_doc(lines, cur_indent + 2))
            elif ':' in val:
                lines[0] = " " * (cur_indent + 2) + val
                res.append(parse_yaml_doc(lines, cur_indent + 2))
            else:
                lines.pop(0)
                res.append(parse_scalar(val))
        elif ':' in trimmed:
            if res is None: res = {}
            key, val = trimmed.split(':', 1)
            key = key.strip()
            val = val.strip()
            lines.pop(0)
            if not val:
                res[key] = parse_yaml_doc(lines, cur_indent + 1)
            else:
                res[key] = parse_scalar(val)
        else:
            val = trimmed
            lines.pop(0)
            res = parse_scalar(val)
            break
    return res

def to_yaml(obj, indent=0, list_item=False):
    prefix = " " * indent
    if list_item:
        prefix = prefix[:-2] + "- "

    if isinstance(obj, dict):
        if not obj: return "{}"
        res = []
        for i, (k, v) in enumerate(obj.items()):
            p = prefix if i > 0 or not list_item else " " * (indent - 2) + "- "
            if isinstance(v, (dict, list)) and v:
                res.append(f"{p}{k}:")
                res.append(to_yaml(v, indent + 2))
            else:
                res.append(f"{p}{k}: {to_yaml(v, 0)}")
